--

CREATE TABLE public.payroll (
    id integer NOT NULL,
    employee_id integer,
    month integer,
    year integer,
    basic_salary numeric(10,2),
    overtime_pay numeric(10,2),
    deductions numeric(10,2),
    net_salary numeric(10,2),
    status character varying(20) DEFAULT 'UNPAID'::character varying,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    late_deduction numeric(10,2) DEFAULT 0,
    absent_deduction numeric(10,2) DEFAULT 0,
    government_deduction numeric(10,2) DEFAULT 0,
    cutoff_start date,
    cutoff_end date,
    pay_date date,
    rule_snapshot jsonb,
    leave_conversion numeric DEFAULT 0,
    branch_id integer,
    CONSTRAINT payroll_status_check CHECK (((status)::text = ANY ((ARRAY['PAID'::character varying, 'UNPAID'::character varying])::text[])))
);


